import { useQuery } from '@tanstack/react-query';
import { promotionApi } from '../../api/services';
import { Table, Badge } from '../../components/ui';
import { format } from 'date-fns';

const statusColor = { PENDING: 'yellow', APPROVED: 'green', REJECTED: 'red' };

export default function PromotionsPage() {
  const { data, isLoading } = useQuery({
    queryKey: ['promotions'],
    queryFn: () => promotionApi.getAll({ page: 0, size: 20 }),
  });

  const promotions = data?.data?.data?.content || data?.data?.data || [];

  const columns = [
    { key: 'employeeCode', label: 'Employee' },
    { key: 'fromDesignation', label: 'From Designation' },
    { key: 'toDesignation', label: 'To Designation' },
    { key: 'effectiveDate', label: 'Effective Date', render: (r) => r.effectiveDate ? format(new Date(r.effectiveDate), 'dd MMM yyyy') : '—' },
    { key: 'status', label: 'Status', render: (r) => <Badge label={r.status} color={statusColor[r.status] || 'gray'} /> },
  ];

  return <Table columns={columns} data={promotions} loading={isLoading} />;
}
